mapper.sql:
SELECT objRec.* FROM ( SELECT tmp1.PROD_ID, tmp1.VDATE, IFNULL(tmp1.actEndMDate,tmp1.MDate) MDATE, STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') as holdDate FROM ( SELECT @rownum :=@rownum +1 rownum, A.PROD_ID, A.VDATE, A.MDATE, B.MDATE AS actEndMDate, B.STATUS, IF (@PROD_ID = A.PROD_ID, @rank :=@rank + 1, @rank :=1 ) AS endStatusNo, @PROD_ID := A.PROD_ID FROM (SELECT * FROM CHB_PRD_BASEINFO ORDER BY PROD_ID, UPDATE_TIME ) A, (SELECT @rownum :=0, @PROD_ID := NULL, @rank := 0) tmp LEFT JOIN CHB_PRD_END_SUB B ON A.PROD_ID = B.PROD_ID WHERE A.STATUS != 'D'
#{orgCode,jdbcType=VARCHAR}
AND A.FPROD_ID is null AND STR_TO_DATE(DATE_FORMAT(A.VDATE, '%Y-%m-%d'), '%Y-%m-%d') <= STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') ) tmp1 WHERE endStatusNo = 1 ANDIFNULL(tmp1.STATUS,'01') != '03' AND STR_TO_DATE(DATE_FORMAT(NVL(actEndMDate,MDATE), '%Y-%m-%d'), '%Y-%m-%d') > STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') ) objRec
